#include <iostream>
#include <string>
#include "markdown.h"

std::string markdownToHtml(const std::string& markdownText) {
    markdown::Markdown md;
    std::string htmlText = md.generate(markdownText);
    return htmlText;
}

int main() {
    std::string markdownText = "## Heading
This is a paragraph.";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "HTML HTML: " << htmlText << std::endl;
    return 0;
}
```

